std::shared_ptr<ShaderNode>makeMagpieShaderNode(const ShaderSpec&spec){return std::make_shared<Node>(spec);}
std::shared_ptr<ShaderNode>forkMagpieShaderNode(const std::shared_ptr<ShaderNode>&previous,const ShaderSpec&spec){const auto node=dynamic_cast<const Node*>(previous.get());if(!node)throw std::runtime_error("The Magpie shader clone has an incompatible provider");return std::make_shared<Node>(*node,spec.parameters);}
MagpieGeometry magpieOutputGeometry(const ShaderNode*node,uint32_t inW,uint32_t inH,uint32_t outW,uint32_t outH){const auto value=dynamic_cast<const Node*>(node);return value?value->geometry(inW,inH,outW,outH):MagpieGeometry{outW,outH,{}};}
